-- Version 7: water on the city maps. Udaipur is the City of Lakes and Kolkata sits on the Hooghly, but the maps
-- showed neither. Each city gets `water`: lakes as outlines ({"areas": [{name, ring}]}) and rivers as lines
-- ({"lines": [{name, line}]}), all [longitude, latitude]. The map draws the water first, then the places on it.
-- Shapes from OpenStreetMap (Open Database Licence), simplified to about 10 m; the credit is shown under the map.
-- Earlier migrations have already run on the live site; never edit them, add a new file instead.
ALTER TABLE cities ADD COLUMN water JSONB NOT NULL DEFAULT '{}';
ALTER TABLE cities ADD COLUMN water_source TEXT NOT NULL DEFAULT '';

